#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
# check-sbom-trend.sh — the third-party component count only goes down
# (native first; S-LOW-FRUIT Phase 8, CLAUDE.md). Counted live from the
# lock data, not from sbom/*.json (those are regenerated by hand and go
# stale):
#   go_components      modules in `go list -m all`, the main module excluded
#   rust_components    distinct name@version of what every tracked Cargo.lock has
#                      from a registry or git (testdata and this repo's own crates
#                      excluded; tests/scripts/test_sbom_trend.py)
#   python_components  distinct package names over every tracked *requirements*.txt
#
#   scripts/check-sbom-trend.sh            fail if any count rose above docs/policy/sbom-count-baseline.txt
#   scripts/check-sbom-trend.sh --update   lower the baseline lines that went down (never raises one)
set -euo pipefail
cd "$(dirname "$0")/.."
baseline=docs/policy/sbom-count-baseline.txt

go_n=$(go list -m all | tail -n +2 | wc -l)
mapfile -t locks < <(git ls-files '*Cargo.lock' | grep -v '/testdata/')
rust_n=$(awk '
	function emit() { if (n != "" && s) print n "@" v; n = ""; v = ""; s = 0 }
	FNR == 1 || /^\[\[package\]\]/ { emit() }
	/^name = /    { n = $3 }
	/^version = / { v = $3 }
	/^source = /  { s = 1 }
	END           { emit() }
' "${locks[@]}" | sort -u | wc -l)
mapfile -t reqs < <(git ls-files '*requirements*.txt')
py_n=0
if (( ${#reqs[@]} )); then
	py_n=$(cat "${reqs[@]}" | grep -vE '^\s*(#|$|-)' | sed -E 's/[<>=!~;[ ].*//' | tr 'A-Z_' 'a-z-' | sort -u | grep -c . || true)
fi

declare -A now=([go_components]=$go_n [rust_components]=$rust_n [python_components]=$py_n)
fail=0
for k in go_components rust_components python_components; do
	base=$(sed -nE "s/^${k}=([0-9]+)$/\1/p" "$baseline")
	[[ -n $base ]] || { echo "FAIL: no ${k}= line in ${baseline}"; fail=1; continue; }
	n=${now[$k]}
	if [[ ${1:-} == --update ]]; then
		if (( n < base )); then sed -i "s/^${k}=${base}\$/${k}=${n}/" "$baseline"; echo "${k}: ${base} -> ${n}"; fi
		continue
	fi
	if (( n > base )); then
		echo "FAIL ${k}: ${n} > baseline ${base} (a new third-party component needs Stevie's recorded approval, and the count may not grow)"
		fail=1
	elif (( n < base )); then
		echo "OK ${k}: ${n} (baseline ${base}; lower it with --update)"
	else
		echo "OK ${k}: ${n}"
	fi
done
exit "$fail"
